+function roleMatches(ruleRole: string, roles: string[]): boolean {
+  return ruleRole === "*" || roles.includes(ruleRole);
+}
+
+function actionMatches(ruleAction: string, action: string): boolean {
+  return ruleAction === "*" || ruleAction === action;
+}
+
+function resourceMatches(pattern: string, resource: string): boolean {
+  if (pattern === "*") return true;
+  if (pattern.endsWith("/*")) {
+    return resource.startsWith(pattern.slice(0, -1));
+  }
+  return pattern === resource;
+}
+
 /** Whether one rule applies to a request. See README.md. */
 export function matches(rule: Rule, request: AccessRequest): boolean {
-  throw new Error("not implemented");
+  return (
+    roleMatches(rule.role, request.roles) &&
+    actionMatches(rule.action, request.action) &&
+    resourceMatches(rule.resource, request.resource)
+  );
+}
+
+/** Decide a request and say which rule decided it. */
+export function explain(rules: Rule[], request: AccessRequest): Decision {
+  let firstAllow: Rule | undefined;
+  for (const rule of rules) {
+    if (!matches(rule, request)) continue;
+    if (rule.effect === "deny") return { allowed: false, rule };
+    firstAllow ??= rule;
+  }
+  return firstAllow ? { allowed: true, rule: firstAllow } : { allowed: false, rule: undefined };
 }

